","export class TenantService {
 constructor() {
 this.tenantTable = 'x_146833_tenant_on_tenant';
 this.onboardingTable = 'x_146833_tenant_on_onboarding';
 this.projectTable = 'x_146833_tenant_on_project';
 this.serviceProviderTable = 'x_146833_tenant_on_service_provider';
 this.serviceRequestTable = 'x_146833_tenant_on_service_request';
 }

 async getCurrentUserTenant() {
 try {
 const response = await fetch(`/api/now/table/${this.tenantTable}?sysparm_query=sys_created_by=javascript:gs.getUserID()&sysparm_display_value=all`, {
 method: 'GET',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.error?.message || 'Failed to fetch tenant');
 }

 const data = await response.json();
 return data.result.length > 0 ? data.result[0] : null;
 } catch (error) {
 console.error('Error fetching current user tenant:', error);
 throw error;
 }
 }

 async createTenant(tenantData) {
 try {
 const response = await fetch(`/api/now/table/${this.tenantTable}`, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 },
 body: JSON.stringify(tenantData)
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.error?.message || 'Failed to create tenant');
 }

 const data = await response.json();
 return data.result;
 } catch (error) {
 console.error('Error creating tenant:', error);
 throw error;
 }
 }

 async updateTenant(sysId, tenantData) {
 try {
 const response = await fetch(`/api/now/table/${this.tenantTable}/${sysId}`, {
 method: 'PATCH',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 },
 body: JSON.stringify(tenantData)
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.error?.message || 'Failed to update tenant');
 }

 const data = await response.json();
 return data.result;
 } catch (error) {
 console.error('Error updating tenant:', error);
 throw error;
 }
 }

 async getOnboardingStatus(tenantSysId) {
 try {
 const sysId = typeof tenantSysId === 'object' ? tenantSysId.value : tenantSysId;
 const response = await fetch(`/api/now/table/${this.onboardingTable}?sysparm_query=tenant=${sysId}&sysparm_display_value=all&sysparm_limit=1`, {
 method: 'GET',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.error?.message || 'Failed to fetch onboarding status');
 }

 const data = await response.json();
 return data.result.length > 0 ? data.result[0] : null;
 } catch (error) {
 console.error('Error fetching onboarding status:', error);
 throw error;
 }
 }

 async getTenantById(sysId) {
 try {
 const id = typeof sysId === 'object' ? sysId.value : sysId;
 const response = await fetch(`/api/now/table/${this.tenantTable}/${id}?sysparm_display_value=all`, {
 method: 'GET',
