export default function TenantRegistration({ service, onSuccess }) {
 const [formData, setFormData] = useState({
 company_name: '',
 contact_email: '',
 contact_phone: '',
 primary_contact: '',
 business_type: '',
 company_size: '',
 marketplace_interests: '',
 technical_requirements: ''
 });

 const [errors, setErrors] = useState({});
 const [isSubmitting, setIsSubmitting] = useState(false);
 const [submitError, setSubmitError] = useState(null);

 const businessTypes = [
 { value: 'startup', label: 'Startup' },
 { value: 'enterprise', label: 'Enterprise' },
 { value: 'government', label: 'Government' },
 { value: 'nonprofit', label: 'Non-Profit' },
 { value: 'individual', label: 'Individual Developer' }
 ];

 const companySizes = [
 { value: 'small', label: '1-50 employees' },
 { value: 'medium', label: '51-500 employees' },
 { value: 'large', label: '501-5000 employees' },
 { value: 'enterprise', label: '5000+ employees' }
 ];

 const handleChange = (e) => {
 const { name, value } = e.target;
 setFormData(prev => ({
 ...prev,
 [name]: value
 }));

 // Clear error when user starts typing
 if (errors[name]) {
 setErrors(prev => ({
 ...prev,
 [name]: ''
 }));
 }
 };

 const validateForm = () => {
 const newErrors = {};

 if (!formData.company_name.trim()) {
 newErrors.company_name = 'Company name is required';
 }

 if (!formData.contact_email.trim()) {
 newErrors.contact_email = 'Contact email is required';
 } else if (!/\S+@\S+\.\S+/.test(formData.contact_email)) {
 newErrors.contact_email = 'Please enter a valid email address';
 }

 if (!formData.primary_contact.trim()) {
 newErrors.primary_contact = 'Primary contact is required';
 }

 if (!formData.business_type) {
 newErrors.business_type = 'Please select a business type';
 }

 if (!formData.company_size) {
 newErrors.company_size = 'Please select company size';
 }

 if (!formData.marketplace_interests.trim()) {
 newErrors.marketplace_interests = 'Please describe your marketplace interests';
 }

 if (!formData.technical_requirements.trim()) {
 newErrors.technical_requirements = 'Please describe your technical requirements';
 }

 setErrors(newErrors);
 return Object.keys(newErrors).length === 0;
 };

 const handleSubmit = async (e) => {
 e.preventDefault();

 if (!validateForm()) {
 return;
 }

 setIsSubmitting(true);
 setSubmitError(null);

 try {
 const tenant = await service.createTenant(formData);
 onSuccess(tenant);
 } catch (error) {
 setSubmitError(error.message || 'Failed to submit registration. Please try again.');
 } finally {
 setIsSubmitting(false);
 }
 };

 return (
 <div className="registration-container">
 <div className="registration-card">
 <div className="card-header">
