 {submitError}
 </div>
 )}

 <form onSubmit={handleSubmit} className="registration-form">
 <div className="form-row">
 <div className="form-group">
 <label className="form-label" htmlFor="company_name">
 Company Name *
 </label>
 <input
 type="text"
 id="company_name"
 name="company_name"
 className={`form-control ${errors.company_name ? 'is-invalid' : ''}`}
 value={formData.company_name}
 onChange={handleChange}
 placeholder="Enter your company name"
 />
 {errors.company_name && (
 <div className="invalid-feedback">{errors.company_name}</div>
 )}
 </div>

 <div className="form-group">
 <label className="form-label" htmlFor="contact_email">
 Contact Email *
 </label>
 <input
 type="email"
 id="contact_email"
 name="contact_email"
 className={`form-control ${errors.contact_email ? 'is-invalid' : ''}`}
 value={formData.contact_email}
 onChange={handleChange}
 placeholder="Enter your contact email"
 />
 {errors.contact_email && (
 <div className="invalid-feedback">{errors.contact_email}</div>
 )}
 </div>
 </div>

 <div className="form-row">
 <div className="form-group">
 <label className="form-label" htmlFor="primary_contact">
 Primary Contact Person *
 </label>
 <input
 type="text"
 id="primary_contact"
 name="primary_contact"
 className={`form-control ${errors.primary_contact ? 'is-invalid' : ''}`}
 value={formData.primary_contact}
 onChange={handleChange}
 placeholder="Enter primary contact name"
 />
 {errors.primary_contact && (
 <div className="invalid-feedback">{errors.primary_contact}</div>
 )}
 </div>

 <div className="form-group">
 <label className="form-label" htmlFor="contact_phone">
 Contact Phone
 </label>
 <input
 type="tel"
 id="contact_phone"
 name="contact_phone"
 className="form-control"
 value={formData.contact_phone}
 onChange={handleChange}
 placeholder="Enter contact phone number"
 />
 </div>
 </div>

 <div className="form-row">
 <div className="form-group">
 <label className="form-label" htmlFor="business_type">
 Business Type *
 </label>
 <select
 id="business_type"
 name="business_type"
 className={`form-control ${errors.business_type ? 'is-invalid' : ''}`}
 value={formData.business_type}
 onChange={handleChange}
 >
 <option value="">Select business type</option>
 {businessTypes.map(type => (
 <option key={type.value} value={type.value}>
 {type.label}
 </option>
 ))}
 </select>
 {errors.business_type && (
 <div className="invalid-feedback">{errors.business_type}</div>
 )}
 </div>

 <div className="form-group">
 <label className="form-label" htmlFor="company_size">
 Company Size *
 </label>
 <select
 id="company_size"
 name="company_size"
 className={`form-control ${errors.company_size ? 'is-invalid' : ''}`}
 value={formData.company_size}
 onChange={handleChange}
 >
 <option value="">Select company size</option>
 {companySizes.map(size => (
 <option key={size.value} value={size.value}>
 {size.label}
 </option>
 ))}
 </select>
 {errors.company_size && (
 <div className="invalid-feedback">{errors.company_size}</div>
 )}
 </div>
 </div>

 <div className="form-group">
 <label className="form-label" htmlFor="marketplace_interests">
 Marketplace Interests *
 </label>
 <textarea
 id="marketplace_interests"
 name="marketplace_interests"
 className={`form-control ${errors.marketplace_interests ? 'is-invalid' : ''}`}
 value={formData.marketplace_interests}
 onChange={handleChange}
 placeholder="Describe what you're looking for in our marketplace (APIs, services, tools, etc.)"
 rows="3"
 />
 {errors.marketplace_interests && (
 <div className="invalid-feedback">{errors.marketplace_interests}</div>
 )}
 </div>

 <div className="form-group">
 <label className="form-label" htmlFor="technical_requirements">
 Technical Requirements *
 </label>
 <textarea
