 setLoading(true);
 const status = await service.getOnboardingStatus(tenant.sys_id);
 setOnboardingStatus(status);
 } catch (err) {
 setError('Failed to load onboarding status');
 console.error('Error loading onboarding status:', err);
 } finally {
 setLoading(false);
 }
 };

 const getStatusColor = (status) => {
 const statusValue = typeof status === 'object' ? status.display_value : status;
 switch (statusValue) {
 case 'Pending Review': return 'warning';
 case 'Approved': return 'success';
 case 'Active': return 'success';
 case 'Rejected': return 'danger';
 case 'Suspended': return 'danger';
 default: return 'secondary';
 }
 };

 const getOnboardingStageProgress = (stage) => {
 const stageValue = typeof stage === 'object' ? stage.display_value : stage;
 const stages = {
 'Registration Submitted': 15,
 'Under Review': 25,
 'Documentation Required': 40,
 'Technical Setup': 60,
 'Testing Phase': 80,
 'Final Approval': 95,
 'Onboarding Complete': 100,
 'Onboarding Failed': 0
 };
 return stages[stageValue] || 0;
 };

 const formatDate = (dateField) => {
 if (!dateField) return 'Not set';
 const dateValue = typeof dateField === 'object' ? dateField.display_value : dateField;
 return new Date(dateValue).toLocaleDateString();
 };

 const extractValue = (field) => {
 return typeof field === 'object' ? field.display_value || field.value : field;
 };

 if (loading) {
