import { TenantService } from './services/TenantService.js';
import TenantRegistration from './components/TenantRegistration.jsx';
import TenantDashboard from './components/TenantDashboard.jsx';
import Header from './components/Header.jsx';
import './app.css';

export default function App() {
 const tenantService = useMemo(() => new TenantService(), []);
 const [currentView, setCurrentView] = useState('register');
 const [userTenant, setUserTenant] = useState(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 checkExistingTenant();
 }, []);

 const checkExistingTenant = async () => {
 try {
 setLoading(true);
 const tenant = await tenantService.getCurrentUserTenant();
 if (tenant) {
 setUserTenant(tenant);
 setCurrentView('dashboard');
 }
 } catch (error) {
 console.error('Error checking existing tenant:', error);
 } finally {
 setLoading(false);
 }
 };

 const handleRegistrationSuccess = (tenant) => {
 setUserTenant(tenant);
 setCurrentView('dashboard');
 };

 const handleViewChange = (view) => {
 setCurrentView(view);
 };

 if (loading) {
 return (
 <div className="loading-container">
 <div className="spinner"></div>
 <p>Loading...</p>
 </div>
 );
 }

 return (
 <div className="tenant-portal">
 <Header 
 currentView={currentView} 
 onViewChange={handleViewChange}
 hasTenant={!!userTenant}
 />

 <main className="main-content">
 {currentView === 'register' && !userTenant && (
 <TenantRegistration 
 service={tenantService}
 onSuccess={handleRegistrationSuccess}
 />
 )}

 {currentView === 'dashboard' && userTenant && (
 <TenantDashboard 
 tenant={userTenant}
 service={tenantService}
 onUpdate={checkExistingTenant}
 />
 )}

 {!userTenant && currentView === 'dashboard' && (
 <div className="no-tenant-message">
 <h2>No Registration Found</h2>
 <p>You don't have a tenant registration yet. Please register first.</p>
 <button 
 className="btn btn-primary"
 onClick={() => setCurrentView('register')}
 >
 Register Now
 </button>
 </div>
 )}
 </main>
 </div>
 );
